command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
$branch="work/f5-f6-semantics-20261006"
$baseline="4f03ea8bc499cd8e4d064431753d4f7aefac0fff"
$accepted="6e43a8d9ee63b144741a0d4fac8c2f3a48fb6ca6"
$candidate="21fcaa28aa11dc72cfae42d9cd32010298adfff4"
$temp=Join-Path $env:RUNNER_TEMP ("f5-f6-docs-"+$env:GITHUB_RUN_ID)
$worktreeAdded=$false
try {
  Set-Location -LiteralPath $repo
  & git fetch origin main $branch --no-tags --prune
  if($LASTEXITCODE -ne 0){throw "candidate fetch failed"}
  $mainSha=(& git rev-parse refs/remotes/origin/main).Trim()
  $branchSha=(& git rev-parse ("refs/remotes/origin/"+$branch)).Trim()
  if($mainSha -ne $baseline){throw "main moved before F5/F6 docs validation: $mainSha"}
  if($branchSha -ne $candidate){throw "candidate moved before F5/F6 docs validation: $branchSha"}

  & git diff --quiet $accepted $candidate -- app/winui tests/winui
  if($LASTEXITCODE -ne 0){throw "accepted F5/F6 product or test files changed after #453"}

  & git worktree add --detach $temp $candidate
  if($LASTEXITCODE -ne 0){throw "candidate worktree creation failed"}
  $worktreeAdded=$true
  Set-Location -LiteralPath $temp
  $env:PYTHONIOENCODING="utf-8"

  & git diff --check $baseline $candidate
  if($LASTEXITCODE -ne 0){throw "git diff --check failed"}

  & cmd /c test.bat policy
  if($LASTEXITCODE -ne 0){throw "policy validation failed"}

  & python -X utf8 -m unittest tests.winui.test_shortcut_semantics_contract
  if($LASTEXITCODE -ne 0){throw "shortcut source contract failed"}

  Write-Host ("F5_F6_ACCEPTED_PRODUCT_SHA="+$accepted)
  Write-Host ("F5_F6_FINAL_BRANCH_SHA="+$candidate)
  Write-Host "F5_F6_DOCS_VALIDATION=PASS"
} finally {
  Set-Location -LiteralPath $repo
  if($worktreeAdded){
    & git worktree remove --force $temp 2>$null
    & git worktree prune
  } elseif(Test-Path -LiteralPath $temp) {
    Remove-Item -LiteralPath $temp -Recurse -Force -ErrorAction SilentlyContinue
  }
}
